doc = {"a": {"b": 1, "c": [10, 20]}, "d": 2}
flat = {}
def flat_walk(node, prefix=""):
    if isinstance(node, dict):
        for k, v in node.items(): flat_walk(v, prefix + k + ".")
    elif isinstance(node, list):
        for i, v in enumerate(node): flat_walk(v, "%s%d." % (prefix, i))
    else:
        flat[prefix[:-1]] = node
flat_walk(doc)
print(flat)

